/* Work-owned WebGL miniature and projected local drawer-axis gesture. */
(function(root){'use strict';const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),copy=x=>JSON.parse(JSON.stringify(x));
function validate(c){if(!c||![c.open,c.range,c.response,c.camera].every(Number.isFinite)||c.range<.2||c.range>1.4||c.open<0||c.open>c.range||c.response<.1||c.response>2||c.camera<-.9||c.camera>.9)throw Error('引き出しの状態が範囲外です');return copy(c);}
class Drawer{constructor(c){this.config=validate(c);this.reset();}reset(){this.position=this.config.open;this.velocity=0;this.target=this.position;}release(){this.target=this.position<this.config.range/2?0:this.config.range;}step(dt,target){if(target!==null)this.target=clamp(target,0,this.config.range);const stiffness=50/this.config.response,damping=12/Math.sqrt(this.config.response);this.velocity+=((this.target-this.position)*stiffness-this.velocity*damping)*dt;this.position=clamp(this.position+this.velocity*dt,0,this.config.range);}}
if(typeof module!=='undefined'&&module.exports){module.exports={Drawer,validate};return;}
const canvas=document.querySelector('canvas'),note=document.querySelector('[role=status]');let config={open:.15,range:1,response:.65,camera:.45},model=new Drawer(config),editing=false,paused=false,grab=null,last=0,bridge;
let renderer;try{renderer=root.DrawerView.create(canvas);}catch(e){note.textContent='WebGLを起動できません：'+e.message;return;}
function restore(c){config=validate(c);model=new Drawer(config);grab=null;}
function screen(){return renderer.mapping(model.position,config.camera);}
canvas.addEventListener('pointerdown',e=>{if(grab)return;const map=screen(),r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(!map.hit(x,y))return;grab={id:e.pointerId,x,y,base:model.position,map};canvas.setPointerCapture(e.pointerId);if(editing)bridge?.changed('begin');});
canvas.addEventListener('pointermove',e=>{if(grab?.id!==e.pointerId)return;const r=canvas.getBoundingClientRect(),position=clamp(grab.base+grab.map.delta(e.clientX-r.left-grab.x,e.clientY-r.top-grab.y),0,config.range);if(editing){config.open=position;model=new Drawer(config);bridge?.changed('move');}else model.target=position;});
const finish=e=>{if(grab?.id!==e.pointerId)return;grab=null;if(editing)bridge?.changed('end');else model.release();};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);
function loop(t){renderer.resize();if(!paused&&!editing)model.step(Math.min(.03,(t-last)/1000||.016),null);last=t;renderer.draw(model.position,config.camera);requestAnimationFrame(loop);}requestAnimationFrame(loop);
bridge=root.FeelBridge?.connect({play(){paused=false;},pause(v){paused=v;grab=null;},reset(){model.reset();grab=null;},getState:()=>copy(config),restoreState:restore,getEditableElements:()=>[{id:'pose',type:'position',control:'work',label:'引き出しの開始姿勢',hint:'模型のつまみを直接引く。作品が投影した可動軸で操作します。'},{id:'range',type:'range',label:'引き出せる長さ',min:.2,max:1.4,step:.05,value:config.range,unit:'模型単位'},{id:'response',type:'timing',label:'追いつく時間',min:.1,max:2,step:.05,value:config.response,unit:'秒'},{id:'camera',type:'value',label:'見る向き',min:-.9,max:.9,step:.05,value:config.camera,unit:'rad'}],beginEdit(){editing=true;grab=null;note.textContent='つまみを引いて開始姿勢を指定';},applyEdit(id,change){const c=copy(config);if(!['range','response','camera'].includes(id))throw Error('この位置は模型内で操作してください');c[id]=change.value;if(id==='range')c.open=Math.min(c.open,c.range);restore(c);},endEdit(id){if(id===null){editing=false;note.textContent='つまみを引いて開ける';}},getComparisonInfo:()=> 'Bはばねで追従し、離すと近い端に収まる。模型のZ軸だけを操作します。'});
note.textContent='つまみを引いて開ける';document.addEventListener('visibilitychange',()=>{paused=document.hidden;grab=null;});
})(typeof window!=='undefined'?window:globalThis);
